answer.sql:
SELECT COUNT(CASE WHEN z.city = 'Aguada' THEN a.alias END) - COUNT(CASE WHEN z.city = 'Aguadilla' THEN a.alias END) AS difference
FROM alias AS a
JOIN zip_data AS z ON z.zip_code = a.zip_code;

